sealed class FfiMigrationResult {
    
    data class Migrated(
        val `newKid`: kotlin.String) : FfiMigrationResult() {
        companion object
    }
    
    data class ReEnrollmentRequired(
        val `oldKid`: kotlin.String) : FfiMigrationResult() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiMigrationResult : FfiConverterRustBuffer<FfiMigrationResult>{
    override fun read(buf: ByteBuffer): FfiMigrationResult {
        return when(buf.getInt()) {
            1 -> FfiMigrationResult.Migrated(
                FfiConverterString.read(buf),
                )
            2 -> FfiMigrationResult.ReEnrollmentRequired(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiMigrationResult) = when(value) {
        is FfiMigrationResult.Migrated -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`newKid`)
            )
        }
        is FfiMigrationResult.ReEnrollmentRequired -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`oldKid`)
            )
        }
    }

    override fun write(value: FfiMigrationResult, buf: ByteBuffer) {
        when(value) {
            is FfiMigrationResult.Migrated -> {
                buf.putInt(1)
                FfiConverterString.write(value.`newKid`, buf)
                Unit
            }
            is FfiMigrationResult.ReEnrollmentRequired -> {
                buf.putInt(2)
                FfiConverterString.write(value.`oldKid`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





sealed class FfiOperationProgress {
    
    data class Started(
        val `operation`: kotlin.String) : FfiOperationProgress() {
        companion object
    }
    
    data class NetworkRoundTrip(
        val `step`: kotlin.UInt, 
        val `total`: kotlin.UInt) : FfiOperationProgress() {
        companion object
    }
    
    object WaitingForUser : FfiOperationProgress()
    
    
    object Complete : FfiOperationProgress()
    
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiOperationProgress : FfiConverterRustBuffer<FfiOperationProgress>{
    override fun read(buf: ByteBuffer): FfiOperationProgress {
        return when(buf.getInt()) {
            1 -> FfiOperationProgress.Started(
                FfiConverterString.read(buf),
                )
            2 -> FfiOperationProgress.NetworkRoundTrip(
                FfiConverterUInt.read(buf),
                FfiConverterUInt.read(buf),
                )
            3 -> FfiOperationProgress.WaitingForUser
            4 -> FfiOperationProgress.Complete
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiOperationProgress) = when(value) {
        is FfiOperationProgress.Started -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`operation`)
            )
        }
        is FfiOperationProgress.NetworkRoundTrip -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUInt.allocationSize(value.`step`)
                + FfiConverterUInt.allocationSize(value.`total`)
            )
        }
        is FfiOperationProgress.WaitingForUser -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is FfiOperationProgress.Complete -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
    }

    override fun write(value: FfiOperationProgress, buf: ByteBuffer) {
        when(value) {
            is FfiOperationProgress.Started -> {
                buf.putInt(1)
                FfiConverterString.write(value.`operation`, buf)
                Unit
            }
            is FfiOperationProgress.NetworkRoundTrip -> {
                buf.putInt(2)
                FfiConverterUInt.write(value.`step`, buf)
                FfiConverterUInt.write(value.`total`, buf)
                Unit
            }
            is FfiOperationProgress.WaitingForUser -> {
                buf.putInt(3)
                Unit
            }
            is FfiOperationProgress.Complete -> {
                buf.putInt(4)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







